def splitArraySameAverage(nums: list[int]) -> bool:
    n = len(nums)
    total = sum(nums)
    m = n // 2
    # sum(A) / len(A) == total / n  => sum(A) = total * len(A) / n (must be integer)
    possible = any((total * k) % n == 0 for k in range(1, m + 1))
    if not possible: return False
    dp = [set() for _ in range(m + 1)]
    dp[0].add(0)
    for num in nums:
        for k in range(m, 0, -1):
            for s in dp[k - 1]:
                dp[k].add(s + num)
    for k in range(1, m + 1):
        if (total * k) % n == 0 and (total * k) // n in dp[k]:
            return True
    return False

